import React from 'react';
import ReactDOM from 'react-dom/client';

function WeatherApp() {
  const styles = {
    container: {
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      minHeight: '100vh',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      padding: '20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, sans-serif'
    },
    card: {
      background: 'rgba(255, 255, 255, 0.9)',
      borderRadius: '20px',
      padding: '30px',
      maxWidth: '500px',
      width: '100%',
      color: '#333',
      boxShadow: '0 20px 40px rgba(0,0,0,0.1)'
    },
    header: {
      textAlign: 'center',
      marginBottom: '25px'
    },
    datetime: {
      fontSize: '14px',
      color: '#666',
      marginBottom: '5px'
    },
    conditionRow: {
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'baseline',
      gap: '10px',
      margin: '10px 0'
    },
    condition: {
      fontSize: '28px',
      fontWeight: 500
    },
    temperature: {
      fontSize: '48px',
      fontWeight: 300,
      letterSpacing: '-1px'
    },
    location: {
      fontSize: '16px',
      color: '#666',
      marginTop: '5px'
    },
    statsContainer: {
      display: 'flex',
      justifyContent: 'space-between',
      margin: '25px 0',
      padding: '20px 0',
      borderTop: '1px solid #e0e0e0',
      borderBottom: '1px solid #e0e0e0'
    },
    statItem: {
      textAlign: 'center'
    },
    statValue: {
      fontSize: '20px',
      fontWeight: 600,
      color: '#667eea',
      marginBottom: '5px'
    },
    statLabel: {
      fontSize: '13px',
      color: '#666',
      textTransform: 'uppercase'
    },
    detailsContainer: {
      display: 'flex',
      justifyContent: 'space-between',
      margin: '25px 0',
      padding: '20px 0',
      borderBottom: '1px solid #e0e0e0'
    },
    detailItem: {
      display: 'flex',
      flexDirection: 'column'
    },
    detailLabel: {
      fontSize: '14px',
      color: '#666',
      marginBottom: '5px'
    },
    detailValue: {
      fontSize: '18px',
      fontWeight: 600
    },
    forecastContainer: {
      marginTop: '20px'
    },
    daysRow: {
      display: 'flex',
      justifyContent: 'space-between',
      marginBottom: '15px'
    },
    day: {
      fontSize: '16px',
      color: '#666',
      flex: 1,
      textAlign: 'center',
      fontWeight: 500
    },
    tempsRow: {
      display: 'flex',
      justifyContent: 'space-between'
    },
    tempItem: {
      flex: 1,
      textAlign: 'center',
      fontSize: '24px',
      fontWeight: 400,
      padding: '8px 0'
    },
    tempLow: {
      color: '#666',
      fontSize: '20px'
    }
  };

  const weatherData = {
    dateTime: 'Tuesday, 11:56',
    condition: 'Cloudy',
    temperature: '10°C',
    location: 'Kyiv, Ukraine',
    stats: [
      { value: '4.53 cm', label: 'Precipitation' },
      { value: '15 h 32 m', label: 'Daylight' },
      { value: '8.13 pm', label: 'Sunset' }
    ],
    details: [
      { label: 'Rain', value: '90%' },
      { label: 'Humidity', value: '73%' },
      { label: 'Wind', value: '10 km/h' }
    ],
    weeklyForecast: [
      { day: 'Today', high: '10°', low: '1°' },
      { day: 'Wed', high: '10°', low: '1°' },
      { day: 'Thu', high: '10°', low: '1°' },
      { day: 'Fri', high: '10°', low: '1°' },
      { day: 'Sat', high: '10°', low: '1°' },
      { day: 'Sun', high: '10°', low: '1°' },
      { day: 'Mon', high: '10°', low: '1°' }
    ]
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        {/* Header */}
        <div style={styles.header}>
          <div style={styles.datetime}>{weatherData.dateTime}</div>
          <div style={styles.conditionRow}>
            <span style={styles.condition}>{weatherData.condition}</span>
            <span style={styles.temperature}>{weatherData.temperature}</span>
          </div>
          <div style={styles.location}>{weatherData.location}</div>
        </div>

        {/* Stats */}
        <div style={styles.statsContainer}>
          {weatherData.stats.map((stat, index) => (
            <div key={index} style={styles.statItem}>
              <div style={styles.statValue}>{stat.value}</div>
              <div style={styles.statLabel}>{stat.label}</div>
            </div>
          ))}
        </div>

        {/* Details */}
        <div style={styles.detailsContainer}>
          {weatherData.details.map((detail, index) => (
            <div key={index} style={styles.detailItem}>
              <span style={styles.detailLabel}>{detail.label}</span>
              <span style={styles.detailValue}>{detail.value}</span>
            </div>
          ))}
        </div>

        {/* Weekly Forecast */}
        <div style={styles.forecastContainer}>
          <div style={styles.daysRow}>
            {weatherData.weeklyForecast.map((day, index) => (
              <div key={index} style={styles.day}>{day.day}</div>
            ))}
          </div>
          
          <div style={styles.tempsRow}>
            {weatherData.weeklyForecast.map((day, index) => (
              <div key={index} style={styles.tempItem}>{day.high}</div>
            ))}
          </div>
          
          <div style={styles.tempsRow}>
            {weatherData.weeklyForecast.map((day, index) => (
              <div key={index} style={{...styles.tempItem, ...styles.tempLow}}>{day.low}</div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

// Render the app
const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<WeatherApp />);
